<style>
body{margin:0;background:#101810;color:#f3f3df;font:15px/1.55 Arial,sans-serif}main{max-width:900px;margin:28px auto;padding:28px;border:1px solid #47543c;border-top:4px solid #b9d66b;border-radius:14px}.brand{display:flex;align-items:center;gap:18px}.logo{width:112px;height:112px;object-fit:contain;flex-shrink:0}header{display:flex;justify-content:space-between;gap:20px}section{border:1px solid #47543c;border-top:3px solid #b9d66b;border-radius:10px;padding:18px;margin:18px 0}h1{font-size:24px}h2{font-size:17px;margin-top:0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}dt{color:#b9d66b}dd{margin:0 0 12px;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:8px;border-bottom:1px solid #47543c}a,button{background:#dce98e;color:#101810;padding:10px 14px;border-radius:8px;border:0;text-decoration:none;cursor:pointer}.actions{display:flex;gap:12px}.muted{font-size:13px;color:#bdc5b0}@media(max-width:600px){main{margin:10px;padding:16px}.grid{grid-template-columns:1fr}}@media print{body{background:white;color:black}main{margin:0;max-width:none}.actions{display:none}section{break-inside:avoid}.muted,dt{color:#333}}
</style>
